primaryQuery:
run: order_items -> {
  where: status != 'Cancelled' and status != 'Returned'
  aggregate: lifetime_spend is sale_price.sum()
}

verifyQuery:
run: order_items -> {
  aggregate:
    all_sales is sale_price.sum()
    cancelled is sale_price.sum() { where: status = 'Cancelled' }
    returned is sale_price.sum() { where: status = 'Returned' }
} -> { select: lifetime_spend is all_sales - cancelled - returned }
